#[cfg(test)]
mod tests {
    /// The enums defined outside this file accept every value of their schema.
    #[test]
    fn external_enums_accept_the_schema_values() {
        // CalibrationSpec.kind
        for v in ["alloc", "survival", "nt_touch", "latency"] {
            let r = serde_json::from_value::<crate::json::CalibrationKind>(serde_json::json!(v));
            assert!(r.is_ok(), "CalibrationSpec.kind: {v}");
        }
        // HazardFitSpec.recalibration
        for v in ["isotonic", "none"] {
            let r = serde_json::from_value::<crate::json::Recalibration>(serde_json::json!(v));
            assert!(r.is_ok(), "HazardFitSpec.recalibration: {v}");
        }
        // LiveImportSpec.venue
        for v in [
            "binance",
            "bybit",
            "okx",
            "coinbase",
            "kraken",
            "deribit",
            "hyperliquid",
            "ibkr_flex",
            "fix44",
            "sim_hftbacktest",
            "sim_nautilus",
            "freqtrade",
            "hummingbot",
            "sim_freqtrade",
            "sim_hummingbot",
            "sim_backtrader",
            "sim_vectorbt",
            "sim_lean",
            "sim_backtesting_py",
        ] {
            let r = serde_json::from_value::<crate::live_venue::LiveVenue>(serde_json::json!(v));
            assert!(r.is_ok(), "LiveImportSpec.venue: {v}");
        }
        // ScorecardSpec.markout_refs[]
        for v in ["mid", "microprice"] {
            let r = serde_json::from_value::<crate::json::MarkoutRef>(serde_json::json!(v));
            assert!(r.is_ok(), "ScorecardSpec.markout_refs[]: {v}");
        }
        // FdrSpec.method
        for v in ["bh", "by"] {
            let r = serde_json::from_value::<crate::json::FdrMethod>(serde_json::json!(v));
            assert!(r.is_ok(), "FdrSpec.method: {v}");
        }
        // ExportSpec.target
        for v in ["hftbacktest", "nautilus", "l2_npz", "latency_npz"] {
            let r = serde_json::from_value::<crate::json::ExportTarget>(serde_json::json!(v));
            assert!(r.is_ok(), "ExportSpec.target: {v}");
        }
    }
}
